from typing import Dict, Tuple
Variable = Tuple[int, int]

def aggregate(m: int, n: int) -> tuple[Dict[Variable,int], int]:
    coeff = {(i,j): 0 for i in range(m) for j in range(n)}
    bound = 0
    for i in range(m):
        bound += 1
        for j in range(n): coeff[i,j] += 1
    for j in range(n):
        bound -= 1
        for i in range(m): coeff[i,j] -= 1
    return coeff, bound

for m,n in [(4,3),(3,3),(2,5)]:
    c,b=aggregate(m,n)
    print(f"{m} by {n}: nonzero={sum(v != 0 for v in c.values())}, aggregate={b} <= 0")

